import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText renders a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // subtotal = 47500, vat = 9975, total = 57475
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n5 Development (hour) €95.00 €475.00\nVAT: €99.75\nTotal: €574.75',
  );
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const text = renderInvoiceText(issued.value);
  // subtotal = 47500, vat = 9975, total = 57475
  assert.equal(
    text,
    'INV-2026-0001\nBlue Fern Bakery\n5 Development (hour) €95.00 €475.00\nVAT: €99.75\nTotal: €574.75',
  );
});

test('renderInvoiceText with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // subtotal = 215000, vat = 45150, total = 260150
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n10 Development (hour) €95.00 €950.00\n1 Logo package €1,200.00 €1,200.00\nVAT: €451.50\nTotal: €2,601.50',
  );
});

test('renderInvoiceText with products having different prices', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-06-15',
    lines: [
      { sku: 'COPY-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 5 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '8 Copywriting (hour) €60.00 €480.00');
  assert.equal(lines[3], '5 Icon set (24 icons) €9.80 €49.00');
  assert.equal(lines[4], '100 Printed flyer A4 (each) €0.37 €37.00');
  // subtotal = 480 + 49 + 37 = 566
  // vat = 480*21/100 + 49*21/100 + 37*9/100 = 100.8 + 10.29 + 3.33 = 114.42 -> 11442
  // total = 566 + 114.42 = 680.42 -> 68042
  assert.equal(lines[5], 'VAT: €114.42');
  assert.equal(lines[6], 'Total: €680.42');
});

test('renderInvoiceText displays different customer names', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const result2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result1.ok, true);
  assert.equal(result2.ok, true);

  const text1 = renderInvoiceText(result1.value);
  const text2 = renderInvoiceText(result2.value);

  assert.match(text1, /Northwind Studio/);
  assert.match(text2, /Kite & Co/);
});

test('renderInvoiceText with large quantities', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5000 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // subtotal = 250000, vat = 52500, total = 302500
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n5000 Sticker sheet €0.50 €2,500.00\nVAT: €525.00\nTotal: €3,025.00',
  );
});

test('renderInvoiceText with high-value items', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2 },
      { sku: 'BRAND-BOOK', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '2 Brand workshop (day, VAT exempt) €600.00 €1,200.00');
  assert.equal(lines[3], '3 Brand guidelines document €2,450.00 €7,350.00');
  // subtotal = 120000 + 735000 = 855000
  // vat = 120000*0/100 + 735000*21/100 = 0 + 154350 = 154350
  // total = 855000 + 154350 = 1009350
  assert.equal(lines[4], 'VAT: €1,543.50');
  assert.equal(lines[5], 'Total: €10,093.50');
});

test('renderInvoiceText preserves line order', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'COPY-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[2], '1 Copywriting (hour) €60.00 €60.00');
  assert.equal(lines[3], '1 Development (hour) €95.00 €95.00');
  assert.equal(lines[4], '1 Design work (hour) €85.00 €85.00');
});

