test('renderInvoiceText displays different customer names', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const result2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result1.ok, true);
  assert.equal(result2.ok, true);

  const text1 = renderInvoiceText(result1.value);
  const text2 = renderInvoiceText(result2.value);

  assert.match(text1, /Northwind Studio/);
  assert.match(text2, /Kite & Co/);
});

test('renderInvoiceText with large quantities', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 5000 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // subtotal = 250000, vat = 52500, total = 302500
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n5000 Sticker sheet €0.50 €2,500.00\nVAT: €525.00\nTotal: €3,025.00',
  );
});

test('renderInvoiceText with high-value items', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'WORKSHOP-DAY', qty: 2 },
      { sku: 'BRAND-BOOK', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '2 Brand workshop (day, VAT exempt) €600.00 €1,200.00');
  assert.equal(lines[3], '3 Brand guidelines document €2,450.00 €7,350.00');
  // subtotal = 120000 + 735000 = 855000
  // vat = 120000*0/100 + 735000*21/100 = 0 + 154350 = 154350
  // total = 855000 + 154350 = 1009350
  assert.equal(lines[4], 'VAT: €1,543.50');
  assert.equal(lines[5], 'Total: €10,093.50');
});

test('renderInvoiceText preserves line order', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'COPY-HOUR', qty: 1 },
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'DES-HOUR', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[2], '1 Copywriting (hour) €60.00 €60.00');
  assert.equal(lines[3], '1 Development (hour) €95.00 €95.00');
  assert.equal(lines[4], '1 Design work (hour) €85.00 €85.00');
});

test('renderInvoiceText with issued invoice includes number in header', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(result.ok, true);
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const issued = issueInvoice(result.value, existing);
  assert.equal(issued.ok, true);
  const text = renderInvoiceText(issued.value);
  assert.equal(text.split('\n')[0], 'INV-2026-0003');
});

test('renderInvoiceText displays line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  assert.match(text, /5 Development \(hour\) €95\.00 €475\.00 \(-10%\)/);
});

test('renderInvoiceText displays multiple lines with different discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  assert.match(text, /\(-10%\)/);
  assert.match(text, /\(-20%\)/);
  assert.doesNotMatch(text, /3 Copywriting \(hour\).*\(-/);
});

test('renderInvoiceText with voucher shows voucher line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const text = renderInvoiceText(invoice);
  assert.match(text, /Voucher: -€100\.00/);
});

test('renderInvoiceText displays due date', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  assert.match(text, /Due: 2026-10-21/);
});

test('renderInvoiceText displays paid amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  let issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  issued = recordPayment(issued.value, { amount: 30000, date: '2026-10-08' });
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  assert.match(text, /Paid: €300\.00/);
});

test('renderInvoiceText with multiple payments shows total paid', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  let issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  issued = recordPayment(issued.value, { amount: 20000, date: '2026-10-08' });
  assert.equal(issued.ok, true);
  issued = recordPayment(issued.value, { amount: 25000, date: '2026-10-15' });
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  assert.match(text, /Paid: €450\.00/);
});

test('renderInvoiceText with no discount does not show discount indicator', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.doesNotMatch(lines[2], /\(-/);
});

test('renderInvoiceText without voucher does not show voucher line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  assert.doesNotMatch(text, /Voucher:/);
});

test('renderInvoiceText without payments does not show paid line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const text = renderInvoiceText(issued.value);
  assert.doesNotMatch(text, /Paid:/);
});

test('renderInvoiceText without due date does not show due line', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  assert.doesNotMatch(text, /Due:/);
});

test('renderInvoiceText with all features', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'SAVE', amount: 5000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  let issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);
  issued = recordPayment(issued.value, { amount: 25000, date: '2026-10-08' });
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0001');
  assert.equal(lines[1], 'Northwind Studio');
  assert.match(lines[2], /\(-10%\)/);
  assert.match(text, /Voucher: -€50\.00/);
  assert.match(text, /Due: 2026-10-21/);
  assert.match(text, /Paid: €250\.00/);
});

