import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText renders a draft invoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // subtotal = 47500, vat = 9975, total = 57475
  // dueDate = 2026-11-06 (NET30 default)
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n5 Development (hour) €95.00 €475.00\nVAT: €99.75\nTotal: €574.75\nDue: 2026-11-06',
  );
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);
  const text = renderInvoiceText(issued.value);
  // subtotal = 47500, vat = 9975, total = 57475, dueDate = 2026-11-06
  assert.equal(
    text,
    'INV-2026-0001\nBlue Fern Bakery\n5 Development (hour) €95.00 €475.00\nVAT: €99.75\nTotal: €574.75\nDue: 2026-11-06',
  );
});

test('renderInvoiceText with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  // qty=10 has bulk discount, qty=1 doesn't
  // subtotal = 215000, vat = 44651, total = 257276, dueDate = 2026-11-06
  assert.equal(
    text,
    'DRAFT\nBlue Fern Bakery\n10 Development (hour) €95.00 €950.00\n1 Logo package €1,200.00 €1,200.00\nVAT: €446.51\nTotal: €2,572.76\nDue: 2026-11-06',
  );
});

test('renderInvoiceText with products having different prices', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-06-15',
    lines: [
      { sku: 'COPY-HOUR', qty: 8 },
      { sku: 'ICON-SET', qty: 5 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);
  const text = renderInvoiceText(result.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '8 Copywriting (hour) €60.00 €480.00');
  assert.equal(lines[3], '5 Icon set (24 icons) €9.80 €49.00');
  assert.equal(lines[4], '100 Printed flyer A4 (each) €0.37 €37.00');
  // PRINT-A4 has qty=100, so bulk discount = 92
  // vat = 10080 + 1029 + 325 = 11434 cents
  // total = 56600 - 92 + 11434 = 67942 cents
  assert.equal(lines[5], 'VAT: €114.34');
  assert.equal(lines[6], 'Total: €679.42');
  assert.equal(lines[7], 'Due: 2026-07-15');
});

test('renderInvoiceText displays different customer names', () => {
